import { Component, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { IonContent, NavController } from '@ionic/angular';
import { ActionType } from '@rsApp/modules/utils/enum/enum';

@Component({
  selector: 'shopping-cart-page',
  templateUrl: './shopping-cart.component.html',
  styleUrls: ['./shopping-cart.component.scss'],
})
export class ShoppingCartPageComponent {
  @ViewChild(IonContent) content!: IonContent;
  public innerHtml: string;
  private readonly checkoutReturnFlagKey = 'fromCheckoutAfterSignIn';
  constructor(
    public router: Router,
    public navCtrl: NavController
  ) {
    window.addEventListener('message', (evt) => {
      if (evt.origin !== window.location.origin) return;
      if (evt && evt.data) {
        const { action, upc, itemId } = evt.data;
        if (action && action === 'MagUpdateProductOption') {
          this.router.navigate([`/product/product-detail/${upc}`, { itemId: itemId }]);
        }
      }
    });
  }

  async ionViewWillEnter() {
    // Clear cached for mag-cart-page
    if (this.innerHtml) {
      this.innerHtml = '';
    }

    customElements.whenDefined('mag-cart-page').then(() => {
      this.innerHtml = '<mag-cart-page></mag-cart-page>';
    });

    window.postMessage({ action: ActionType.MagRefreshShoppingCart }, window.location.origin);
    window.addEventListener('scrollToTop', this.handleScrollToTop);
  }

  ionViewWillLeave() {
    window.removeEventListener('scrollToTop', this.handleScrollToTop);
  }

  private handleScrollToTop = () => {
    this.content?.scrollToTop();
  };

  backToPreviousPage() {
    const isComingFromCheckoutAfterSignIn = window.sessionStorage.getItem(this.checkoutReturnFlagKey);

    if (isComingFromCheckoutAfterSignIn === 'true') {
      this.clearCheckoutReturnFlag();
      this.router.navigate(['/tabs/home']);
      return;
    }

    this.navCtrl.back();
  }

  private clearCheckoutReturnFlag(): void {
    if (typeof window === 'undefined') return;
    try {
      window.sessionStorage.removeItem(this.checkoutReturnFlagKey);
    } catch (error) {
      console.warn('Unable to clear checkout return flag', error);
    }
  }
}
